import React, { useCallback, useEffect, useState } from 'react';

import {

  fetchRuntimeHealth,

  loginRequest,

  registerRequest,

  getErrorMessage,

  AuthUserPublic

} from '../api';

import { BrandSchoolChip } from './BrandSchoolChip';



type Mode = 'login' | 'register';



interface LoginPanelProps {

  onLoggedIn: (user: AuthUserPublic) => void;

  onGuest: () => void;

}



export const LoginPanel: React.FC<LoginPanelProps> = ({ onLoggedIn, onGuest }) => {

  const [mode, setMode] = useState<Mode>('login');

  const [username, setUsername] = useState('');

  const [password, setPassword] = useState('');

  const [displayName, setDisplayName] = useState('');

  const [submitting, setSubmitting] = useState(false);

  const [error, setError] = useState<string | null>(null);

  const [backendOk, setBackendOk] = useState<boolean | null>(null);

  const [llmHint, setLlmHint] = useState<string | null>(null);



  const checkBackend = useCallback(async () => {

    try {

      const h = await fetchRuntimeHealth();

      setBackendOk(h.status === 'ok');

      if (h.llmMode === 'zhipu') {

        setLlmHint(`智谱 AI 已连接 · ${h.model || 'glm-4.7-flash'}`);

      } else if (h.llmMode === 'ollama') {

        setLlmHint(`Ollama 已连接 · ${h.model || 'qwen:7b'}`);

      } else if (h.llmMode === 'fast') {

        setLlmHint('当前为快速模式（未使用大模型）');

      } else {

        setLlmHint('大模型未就绪，咨询将使用规则兜底');

      }

      return true;

    } catch {

      setBackendOk(false);

      setLlmHint(null);

      return false;

    }

  }, []);



  useEffect(() => {

    void checkBackend();

    const id = window.setInterval(() => void checkBackend(), 8000);

    return () => window.clearInterval(id);

  }, [checkBackend]);



  const handleSubmit = async (e: React.FormEvent) => {

    e.preventDefault();

    setError(null);

    setSubmitting(true);

    try {

      if (mode === 'login') {

        const data = await loginRequest(username.trim(), password);

        onLoggedIn(data.user);

      } else {

        const data = await registerRequest(username.trim(), password, displayName.trim() || undefined);

        onLoggedIn(data.user);

      }

    } catch (err) {

      setError(getErrorMessage(err));

    } finally {

      setSubmitting(false);

    }

  };



  return (

    <div className="login-overlay">

      <div className="login-card">

        <div className="login-brand">

          <span className="login-brand-icon" aria-hidden="true">

            🌿

          </span>

        </div>

        <div className="login-school-row">

          <BrandSchoolChip className="brand-school-chip-on-card" />

        </div>

        <h2 className="login-title">心理港湾 · 高校心理健康平台</h2>

        <p className="login-desc">学生登录进入咨询端；辅导员/管理员进入学校管理端。也可游客体验学生功能。</p>

        <div className="login-tabs">

          <button

            type="button"

            className={mode === 'login' ? 'active' : ''}

            onClick={() => { setMode('login'); setError(null); }}

          >

            登录

          </button>

          <button

            type="button"

            className={mode === 'register' ? 'active' : ''}

            onClick={() => { setMode('register'); setError(null); }}

          >

            注册新账号

          </button>

        </div>



        {backendOk === true && (

          <div className="login-backend-ok" role="status">

            后端已连接{llmHint ? ` · ${llmHint}` : ''}

          </div>

        )}

        {backendOk === false && (

          <div className="login-backend-warn" role="alert">

            <p>

              后端未连接（端口 3001）。请在 <code>PsyQA</code> 目录双击「一键启动.bat」，或执行{' '}

              <code>npm run dev</code>。若已启动仍失败，在终端执行 <code>npm install</code> 后重启。

            </p>

            <button type="button" className="login-retry-btn" onClick={() => void checkBackend()}>

              重新检测

            </button>

          </div>

        )}



        <form onSubmit={handleSubmit} className="login-form">

          <label>

            <span>用户名（3～24 位，字母/数字/下划线/中文）</span>

            <input

              type="text"

              value={username}

              autoComplete={mode === 'login' ? 'username' : 'new-username'}

              onChange={(e) => setUsername(e.target.value)}

              placeholder={mode === 'login' ? '例如 demo' : '起一个用户名'}

            />

          </label>

          {mode === 'register' && (

            <label>

              <span>显示昵称（可选）</span>

              <input

                type="text"

                value={displayName}

                onChange={(e) => setDisplayName(e.target.value)}

                placeholder="在界面顶部显示的名字"

              />

            </label>

          )}

          <label>

            <span>{mode === 'login' ? '密码' : '密码（不少于 6 位）'}</span>

            <input

              type="password"

              value={password}

              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}

              onChange={(e) => setPassword(e.target.value)}

              placeholder={mode === 'login' ? '密码' : '设置密码'}

            />

          </label>

          {error && <div className="login-error">{error}</div>}

          <button type="submit" className="login-submit" disabled={submitting || backendOk === false}>

            {submitting ? '请稍候…' : mode === 'login' ? '登录' : '注册并登录'}

          </button>

        </form>



        <p className="login-hint">

          学生端：<code>demo</code> / <code>demo123</code>

          {' · '}

          学校端：<code>counselor</code> / <code>counselor123</code> 或 <code>admin</code> / <code>admin123</code>

        </p>



        <button type="button" className="login-guest" onClick={onGuest}>

          暂不登录，游客体验（数据仅存本机浏览器）

        </button>

      </div>

    </div>

  );

};
